/bin/bash -lc 'for z in inputs/scogs_animals.zip inputs/scogs_fungi.zip; do echo "$z"; unzip -Z1 "$z" | awk '"'
function suffix(name) {
 if (name ~ /\\.treefile"'$/) return "treefile";
 if (name ~ /'"\\.bionj"'$/) return "bionj";
 if (name ~ /'"\\.iqtree"'$/) return "iqtree";
 if (name ~ /'"\\.mldist"'$/) return "mldist";
 if (name ~ /'"\\.model\\.gz"'$/) return "model.gz";
 if (name ~ /'"\\.ckp\\.gz"'$/) return "ckp.gz";
 if (name ~ /'"\\.clipkit\\.log"'$/) return "clipkit.log";
 if (name ~ /'"\\.clipkit"'$/) return "clipkit";
 if (name ~ /'"\\.mafft"'$/) return "mafft";
 if (name ~ /'"\\.faa"'$/) return "faa";
 return "other"
}
{c[suffix($0)]++} END{for(k in c) print k,c[k]}'"' | sort; done
command -v phykit || true
python - <<'PY'
try:
 import phykit
 print('phykit', phykit.__version__ if hasattr(phykit,'__version__') else phykit)
except Exception as e: print('no phykit', repr(e))
PY"

